#include<math.h>
#include<stdio.h>

int main(int argc, char *argv[])
{
    double a, b, c;
    scanf("%lf%lf%lf", &a, &b, &c);

    double r=sqrt(b*b-4*a*c);
    double x1=(-b+r)/(2*a);
    double x2=(-b-r)/(2*a);
    if (x1 < x2) {
        double tmp = x1;
        x1 = x2;
        x2 = tmp;
    }
    printf("%.8f\n%.8f", x1, x2);
    return 0;
}

